// Independent reference implementations and hand-predicted bug case tables.
export const recallThinSolutions = {
  'batch-slot-labels':
    'function batchLabels(total: number, capacity: number) { const result: string[] = []; let remaining = total; let batch = 1; while (remaining > 0) { const count = Math.min(remaining, capacity); result.push(`Batch ${batch}: ${count} items`); remaining -= count; batch++ } return result }',
  'inspection-run-summary':
    'function inspectionSummary(readings: number[], limit: number) { let alerts = 0; let run = 0; let longestRun = 0; for (const value of readings) { if (value > limit) { alerts++; run++; longestRun = Math.max(longestRun, run) } else run = 0 } return {alerts, longestRun} }',
  'selection-action-state':
    'function selectionState(rows: {selected:boolean;locked:boolean}[], busy:boolean) { const selected = rows.filter(row => row.selected); const count = selected.length; const message = busy ? "Working" : count === 0 ? "Select rows" : selected.some(row => row.locked) ? "Selection locked" : "Ready"; return {count, enabled: message === "Ready", message} }',
  'navigation-window':
    'function chapterLinks(total:number,current:number,radius:number) { if (!total) return {chapters:[],before:false,after:false}; const center=Math.min(total,Math.max(1,current)); const start=Math.max(1,center-radius); const end=Math.min(total,center+radius); return {chapters:Array.from({length:end-start+1},(_,i)=>start+i),before:start>1,after:end<total} }',
  'conditional-resource-response':
    'function resourceResponse(exists:boolean,revision:string,requestedRevision:string|null,method:string) { if (!exists) return {status:404,revision:null,body:null}; if (requestedRevision === revision) return {status:304,revision,body:null}; return {status:200,revision,body:method === "HEAD" ? null : "Resource data"} }',
  'retry-response-policy':
    'function retryResponse(attempt:number,maximum:number,delaySeconds:number,permanent:boolean) { if (permanent) return {status:400,retryAfter:null,body:"Rejected"}; if (attempt >= maximum) return {status:503,retryAfter:null,body:"Exhausted"}; return {status:429,retryAfter:String(delaySeconds),body:"Retry later"} }',
  'expose-stock-bugs':
    "type Allocate = (stock: number[], wanted: number) => number\nconst implementations: Record<string, Allocate> = {\n  correct: (stock, wanted) => Math.min(stock[0], wanted),\n  'variant-a': (stock, wanted) => Math.max(stock[0], wanted),\n  'variant-b': (stock, wanted) => wanted === 0 ? stock[0] : Math.min(stock[0], wanted),\n  'variant-c': (stock, wanted) => Math.min(stock[0], wanted) - 1,\n  'variant-d': (stock, wanted) => { const count = Math.min(stock[0], wanted); stock[0] -= count; return count },\n}\nconst cases: { value: number[]; argument: number; expected: number }[] = [{'value': [5], 'argument': 2, 'expected': 2}, {'value': [2], 'argument': 5, 'expected': 2}, {'value': [5], 'argument': 0, 'expected': 0}, {'value': [0], 'argument': 3, 'expected': 0}, {'value': [2], 'argument': 2, 'expected': 2}]\nfunction exposes(variant: string): boolean { for (const c of cases) { const copy = [...c.value]; const result = implementations[variant](copy, c.argument); if (result !== c.expected || JSON.stringify(copy) !== JSON.stringify(c.value)) return true } return false }",
  'expose-access-bugs':
    "type Access = (flags: boolean[], age: number) => boolean\nconst implementations: Record<string, Access> = {\n  correct: (flags, age) => flags[0] && !flags[1] && age >= 18,\n  'variant-a': (flags, age) => flags[0] && !flags[1] && age > 18,\n  'variant-b': (flags, age) => (flags[0] || age >= 18) && !flags[1],\n  'variant-c': (flags, age) => flags[0] && age >= 18,\n  'variant-d': (flags, age) => { const active = flags.shift(); const suspended = flags.shift(); return Boolean(active && !suspended && age >= 18) },\n}\nconst cases: { value: boolean[]; argument: number; expected: boolean }[] = [{'value': [true, false], 'argument': 18, 'expected': true}, {'value': [false, false], 'argument': 20, 'expected': false}, {'value': [true, true], 'argument': 20, 'expected': false}, {'value': [true, false], 'argument': 17, 'expected': false}, {'value': [false, true], 'argument': 0, 'expected': false}]\nfunction exposes(variant: string): boolean { for (const c of cases) { const copy = [...c.value]; const result = implementations[variant](copy, c.argument); if (result !== c.expected || JSON.stringify(copy) !== JSON.stringify(c.value)) return true } return false }",
}
